from collections import defaultdict
t = int(input())
for _ in range(t):
	(n, m) = map(int, input().rstrip().split())
	mat = []
	for i in range(n):
		a = list(map(int, input().rstrip().split()))
		if not i & 1:
			mat.append(a)
		else:
			mat.append(a)
	d = defaultdict(lambda : 0)
	for i in mat:
		for j in i:
			d[j] += 1
	mm = [[0] * m for i in range(n)]
	flag = 0
	for i in range(n):
		for j in range(0, m // 2):
			f = 0
			for k in d:
				if d[k] >= 2:
					cur = k
					d[k] -= 2
					f = 1
					break
			if f == 0 and flag != 1:
				print(-1)
				flag = 1
				break
			mm[i][j] = cur
			mm[i][-1 - j] = cur
	if flag != 1:
		if m % 2 == 1:
			for i in range(n):
				for j in d:
					if d[j] >= 1:
						cur = j
						d[j] -= 1
						break
				mm[i][m // 2] = cur
		for i in mm:
			for j in i:
				print(j, end=' ')
			print()
